// Valida la fecha de corte de una factura.
function esBisiesto(a){ return (a%4===0 && a%100!==0) || a%400===0; }
function diasDelMes(m,a){ return [31, esBisiesto(a)?29:28, 31,30,31,30,31,31,30,31,30,31][m-1]; }
module.exports = { esBisiesto, diasDelMes };
=== formato.js ===
// Presentación: lista de nombres de clientes para el encabezado del informe mensual.
function listaClientes(nombres) {
  return nombres.filter(Boolean).join(', ');
}
module.exports = { listaClientes };
=== tarifa.js ===
// Comisión aplicada a cada factura.
const COMISION = 0.02;   // 2 %
function comision(monto){ return Math.round(monto * COMISION * 100) / 100; }
module.exports = { comision, COMISION };

